/*
  Blink
  Turns an LED on for one second, then off for one second, over and over.
  LED on pin 13 through a 220 ohm resistor to GND.
*/

#define LED_PIN 13

void setup() {
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  digitalWrite(LED_PIN, HIGH);   // turn the LED on
  delay(1000);                   // wait a second
  digitalWrite(LED_PIN, LOW);    // turn the LED off
  delay(1000);                   // wait a second
}

