// Push button controls an LED
// Button wired between pin 2 and GND - no extra resistor needed
// because we use the internal pull-up.
// LED on pin 8 with a 220 ohm resistor.

const int buttonPin = 2;
const int ledPin = 8;

void setup() {
  pinMode(buttonPin, INPUT_PULLUP);
  pinMode(ledPin, OUTPUT);
}

void loop() {
  // With INPUT_PULLUP the pin reads HIGH when released, LOW when pressed
  int buttonState = digitalRead(buttonPin);

  if (buttonState == LOW) {
    digitalWrite(ledPin, HIGH);
  } else {
    digitalWrite(ledPin, LOW);
  }
}

