// Blink two LEDs at different speeds without using delay(),
// so both keep their own timing.

const int redLed = 9;
const int greenLed = 10;

unsigned long previousRed = 0;
unsigned long previousGreen = 0;

const long redInterval = 500;     // ms
const long greenInterval = 1200;  // ms

bool redState = false;
bool greenState = false;

void setup() {
  pinMode(redLed, OUTPUT);
  pinMode(greenLed, OUTPUT);
}

void loop() {
  unsigned long now = millis();

  if (now - previousRed >= redInterval) {
    previousRed = now;
    redState = !redState;
    digitalWrite(redLed, redState);
  }

  if (now - previousGreen >= greenInterval) {
    previousGreen = now;
    greenState = !greenState;
    digitalWrite(greenLed, greenState);
  }
}

parts_4.code:
/*
  Simple traffic light
  Red    -> pin 4
  Yellow -> pin 5
  Green  -> pin 6
  Each LED through its own 220 ohm resistor.
*/

int RED_PIN = 4;
int YELLOW_PIN = 5;
int GREEN_PIN = 6;

void setup() {
  pinMode(RED_PIN, OUTPUT);
  pinMode(YELLOW_PIN, OUTPUT);
  pinMode(GREEN_PIN, OUTPUT);
}

void loop() {
  // stop
  digitalWrite(RED_PIN, HIGH);
  delay(5000);
  digitalWrite(RED_PIN, LOW);

  // go
  digitalWrite(GREEN_PIN, HIGH);
  delay(4000);
  digitalWrite(GREEN_PIN, LOW);

  // get ready to stop
  digitalWrite(YELLOW_PIN, HIGH);
  delay(2000);
  digitalWrite(YELLOW_PIN, LOW);
}

