/*
  RGB LED colour fade
  Common cathode RGB LED, every leg through a 220 ohm resistor,
  the long leg to GND.
  R -> 9, G -> 10, B -> 11 (all PWM capable pins)
*/

#define RED_PIN   9
#define GREEN_PIN 10
#define BLUE_PIN  11

void setColour(int red, int green, int blue) {
  analogWrite(RED_PIN, red);
  analogWrite(GREEN_PIN, green);
  analogWrite(BLUE_PIN, blue);
}

void setup() {
  pinMode(RED_PIN, OUTPUT);
  pinMode(GREEN_PIN, OUTPUT);
  pinMode(BLUE_PIN, OUTPUT);
}

void loop() {
  // red to green
  for (int i = 0; i <= 255; i++) {
    setColour(255 - i, i, 0);
    delay(10);
  }

  // green to blue
  for (int i = 0; i <= 255; i++) {
    setColour(0, 255 - i, i);
    delay(10);
  }

  // blue back to red
  for (int i = 0; i <= 255; i++) {
    setColour(i, 0, 255 - i);
    delay(10);
  }
}

