// Read a potentiometer and use it to dim an LED.
// Pot middle pin -> A0, the two outer pins -> 5V and GND.
// LED on pin 6 (PWM).

const int potPin = A0;
const int ledPin = 6;

void setup() {
  Serial.begin(9600);
  pinMode(ledPin, OUTPUT);
}

void loop() {
  int potValue = analogRead(potPin);              // 0 .. 1023
  int brightness = map(potValue, 0, 1023, 0, 255); // 0 .. 255 for analogWrite

  analogWrite(ledPin, brightness);

  Serial.print("pot = ");
  Serial.print(potValue);
  Serial.print("  brightness = ");
  Serial.println(brightness);

  delay(100);
}

