/*
  Automatic night light
  LDR and a 10k resistor form a voltage divider, the junction goes to A0.
  When the room gets dark the LED on pin 3 switches on.
*/

const int LDR_PIN = A0;
const int LED_PIN = 3;
const int THRESHOLD = 400;   // a lower reading means it is darker

void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int light = analogRead(LDR_PIN);
  Serial.println(light);

  if (light < THRESHOLD) {
    digitalWrite(LED_PIN, HIGH);   // dark, lamp on
  } else {
    digitalWrite(LED_PIN, LOW);    // bright enough, lamp off
  }

  delay(200);
}

