/*
  Play a short scale on a passive buzzer.
  Buzzer + -> pin 8, buzzer - -> GND
*/

#define BUZZER 8

// note frequencies in Hz: C4 D4 E4 F4 G4 A4 B4 C5
int melody[] = {262, 294, 330, 349, 392, 440, 494, 523};
int noteCount = 8;
int noteDuration = 300;

void setup() {
  pinMode(BUZZER, OUTPUT);
}

void loop() {
  for (int i = 0; i < noteCount; i++) {
    tone(BUZZER, melody[i], noteDuration);
    delay(noteDuration + 50);   // small gap so the notes do not run together
  }

  noTone(BUZZER);
  delay(2000);
}

