/*
  HC-SR04 ultrasonic distance sensor
  TRIG -> pin 9, ECHO -> pin 10, VCC -> 5V, GND -> GND
  Open the Serial Monitor at 9600 baud to see the distance.
*/

const int trigPin = 9;
const int echoPin = 10;

void setup() {
  Serial.begin(9600);
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
}

void loop() {
  // a 10 microsecond pulse starts a measurement
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  // measure how long the echo pin stays HIGH
  long duration = pulseIn(echoPin, HIGH);

  // sound travels roughly 0.034 cm per microsecond, and the pulse
  // makes the trip twice, so divide by 2
  float distance = duration * 0.034 / 2;

  Serial.print("Distance: ");
  Serial.print(distance);
  Serial.println(" cm");

  delay(500);
}

parts_11.code:
/*
  Parking sensor
  The closer the obstacle, the faster the buzzer beeps.
  HC-SR04: TRIG -> pin 6, ECHO -> pin 7
  Buzzer -> pin 8
*/

#define TRIG_PIN   6
#define ECHO_PIN   7
#define BUZZER_PIN 8

long readDistanceCm() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  // 30 ms timeout so we do not block forever when nothing is in range
  long duration = pulseIn(ECHO_PIN, HIGH, 30000);
  return duration * 0.034 / 2;
}

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  long distance = readDistanceCm();
  Serial.println(distance);

  if (distance > 0 && distance < 50) {
    // the gap between beeps shrinks as you get closer
    int gap = map(distance, 0, 50, 50, 600);
    tone(BUZZER_PIN, 1500, 40);
    delay(gap);
  } else {
    noTone(BUZZER_PIN);
    delay(200);
  }
}

parts_12.code:
/*
  Relay module switched by a push button.
  Relay IN -> pin 7. Most cheap relay boards are active LOW,
  so LOW switches the relay on.
  Button between pin 2 and GND.
*/

const int relayPin = 7;
const int buttonPin = 2;

bool relayOn = false;
int lastReading = HIGH;

void setup() {
  pinMode(relayPin, OUTPUT);
  pinMode(buttonPin, INPUT_PULLUP);
  digitalWrite(relayPin, HIGH);   // start with the relay off
  Serial.begin(9600);
}

void loop() {
  int reading = digitalRead(buttonPin);

  // falling edge = the button was just pressed
  if (lastReading == HIGH && reading == LOW) {
    relayOn = !relayOn;

    if (relayOn) {
      digitalWrite(relayPin, LOW);
      Serial.println("Relay ON");
    } else {
      digitalWrite(relayPin, HIGH);
      Serial.println("Relay OFF");
    }

    delay(50);   // simple debounce
  }

  lastReading = reading;
}

