/*
  Control a servo with a potentiometer.
  Servo signal -> pin 9, servo power from 5V and GND.
  Potentiometer wiper -> A0.
*/

#include <Servo.h>

Servo myservo;

int potPin = A0;
int val = 0;

void setup() {
  myservo.attach(9);
}

void loop() {
  val = analogRead(potPin);          // read the pot, 0 .. 1023
  val = map(val, 0, 1023, 0, 180);   // scale it to a servo angle
  myservo.write(val);
  delay(15);                         // give the servo time to get there
}

parts_14.code:
/*
  L298N motor driver: run one DC motor forwards and backwards.
  ENA -> pin 9 (PWM, speed)
  IN1 -> pin 8
  IN2 -> pin 7
  Motor power goes to the L298N, not to the Arduino.
*/

const int ENA = 9;
const int IN1 = 8;
const int IN2 = 7;

void forward(int speed) {
  digitalWrite(IN1, HIGH);
  digitalWrite(IN2, LOW);
  analogWrite(ENA, speed);
}

void backward(int speed) {
  digitalWrite(IN1, LOW);
  digitalWrite(IN2, HIGH);
  analogWrite(ENA, speed);
}

void stopMotor() {
  digitalWrite(IN1, LOW);
  digitalWrite(IN2, LOW);
  analogWrite(ENA, 0);
}

void setup() {
  pinMode(ENA, OUTPUT);
  pinMode(IN1, OUTPUT);
  pinMode(IN2, OUTPUT);
}

void loop() {
  // gently speed up going forwards
  for (int speed = 100; speed <= 255; speed += 5) {
    forward(speed);
    delay(50);
  }

  stopMotor();
  delay(1000);

  backward(180);
  delay(2000);

  stopMotor();
  delay(1000);
}

