/*
  28BYJ-48 stepper motor driven by a ULN2003 board.
  IN1..IN4 of the driver go to pins 8, 9, 10, 11.
  Watch the order in the constructor: IN1, IN3, IN2, IN4.
*/

#include <Stepper.h>

const int stepsPerRevolution = 2048;   // one full turn of the 28BYJ-48

Stepper myStepper(stepsPerRevolution, 8, 10, 9, 11);

void setup() {
  myStepper.setSpeed(10);   // rpm
  Serial.begin(9600);
}

void loop() {
  Serial.println("clockwise");
  myStepper.step(stepsPerRevolution);
  delay(1000);

  Serial.println("counterclockwise");
  myStepper.step(-stepsPerRevolution);
  delay(1000);
}

parts_16.code:
/*
  Show the distance measured by an HC-SR04 on a 16x2 LCD.
  LCD: RS -> 12, E -> 11, D4..D7 -> 5, 4, 3, 2
  Sensor: TRIG -> 7, ECHO -> 6
*/

#include <LiquidCrystal.h>

LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

const int trigPin = 7;
const int echoPin = 6;

void setup() {
  lcd.begin(16, 2);
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);

  lcd.print("Distance meter");
  delay(1500);
  lcd.clear();
}

void loop() {
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  long duration = pulseIn(echoPin, HIGH);
  int distance = duration * 0.034 / 2;

  lcd.setCursor(0, 0);
  lcd.print("Distance:");
  lcd.setCursor(0, 1);
  lcd.print(distance);
  lcd.print(" cm    ");   // trailing spaces clear the old digits

  delay(300);
}

