/*
  Light level bar graph
  Four LEDs on pins 2, 3, 4, 5 light up one by one as the room gets brighter.
  LDR divider on A1.
*/

int ledPins[] = {2, 3, 4, 5};
int numLeds = 4;
int sensorPin = A1;

void setup() {
  for (int i = 0; i < numLeds; i++) {
    pinMode(ledPins[i], OUTPUT);
  }
  Serial.begin(9600);
}

void loop() {
  int sensorValue = analogRead(sensorPin);
  int level = map(sensorValue, 0, 1023, 0, numLeds);

  Serial.print("light: ");
  Serial.print(sensorValue);
  Serial.print(" -> level ");
  Serial.println(level);

  for (int i = 0; i < numLeds; i++) {
    if (i < level) {
      digitalWrite(ledPins[i], HIGH);
    } else {
      digitalWrite(ledPins[i], LOW);
    }
  }

  delay(150);
}

parts_18.code:
/*
  ESP32: turn an LED on and off from a web browser.
  LED on GPIO 2 (the built-in LED on most dev boards).
  Open the Serial Monitor at 115200 baud to see the IP address,
  then type it into your browser.
*/

#include <WiFi.h>
#include <WebServer.h>

const char* ssid = "YOUR_WIFI_NAME";
const char* password = "YOUR_WIFI_PASSWORD";

const int ledPin = 2;

WebServer server(80);

void handleRoot() {
  String html = "<h1>ESP32 LED</h1>";
  html += "<p><a href=\"/on\">Turn ON</a></p>";
  html += "<p><a href=\"/off\">Turn OFF</a></p>";
  server.send(200, "text/html", html);
}

void handleOn() {
  digitalWrite(ledPin, HIGH);
  handleRoot();
}

void handleOff() {
  digitalWrite(ledPin, LOW);
  handleRoot();
}

void setup() {
  Serial.begin(115200);
  pinMode(ledPin, OUTPUT);

  WiFi.begin(ssid, password);
  Serial.print("Connecting");
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("IP address: ");
  Serial.println(WiFi.localIP());

  server.on("/", handleRoot);
  server.on("/on", handleOn);
  server.on("/off", handleOff);
  server.begin();
}

void loop() {
  server.handleClient();
}

