/*
  ESP32: dim an LED with a potentiometer using the LEDC PWM peripheral.
  Potentiometer wiper -> GPIO 34 (input only pin, ADC1)
  LED -> GPIO 18 through a 220 ohm resistor
*/

const int POT_PIN = 34;
const int LED_PIN = 18;

const int PWM_FREQ = 5000;
const int PWM_RESOLUTION = 8;   // 8 bit gives a duty of 0 .. 255

void setup() {
  Serial.begin(115200);
  ledcAttach(LED_PIN, PWM_FREQ, PWM_RESOLUTION);
}

void loop() {
  int raw = analogRead(POT_PIN);          // the ESP32 ADC is 12 bit: 0 .. 4095
  int duty = map(raw, 0, 4095, 0, 255);

  ledcWrite(LED_PIN, duty);

  Serial.print("raw = ");
  Serial.print(raw);
  Serial.print("  duty = ");
  Serial.println(duty);

  delay(100);
}

