/*
  ESP32: a push button toggles a relay module.
  Button between GPIO 15 and GND (internal pull-up).
  Relay IN -> GPIO 23. This board is active HIGH.
*/

#define BUTTON_PIN 15
#define RELAY_PIN  23

bool relayState = false;
int lastButton = HIGH;
unsigned long lastPress = 0;

void setup() {
  Serial.begin(115200);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(RELAY_PIN, OUTPUT);
  digitalWrite(RELAY_PIN, LOW);
}

void loop() {
  int button = digitalRead(BUTTON_PIN);

  // falling edge, and at least 200 ms since the last press
  if (lastButton == HIGH && button == LOW && millis() - lastPress > 200) {
    lastPress = millis();
    relayState = !relayState;
    digitalWrite(RELAY_PIN, relayState);

    if (relayState) {
      Serial.println("relay on");
    } else {
      Serial.println("relay off");
    }
  }

  lastButton = button;
}
